changeSet.sql:
DO $$ DECLARE tbl TEXT; BEGIN
  FOR tbl IN SELECT table_name FROM information_schema.tables WHERE table_schema='leave_mgmt' LOOP
    EXECUTE format('ALTER TABLE leave_mgmt.%I ENABLE ROW LEVEL SECURITY;', tbl);
    EXECUTE format(
      'CREATE POLICY tenant_isolation ON leave_mgmt.%I USING (tenant_id = COALESCE(NULLIF(current_setting(''app.current_tenant_id'', true), ''''), ''00000000-0000-0000-0000-000000000000'')::uuid);',
      tbl);
  END LOOP;
END $$;
